import{c as s,Q as t,j as n,m as e}from"./chunks/framework.DOi4mjdC.js";const p="/assets/zh-cn_formulaimage_0000001718651312.BEV3W4FU.png",l="/assets/zh-cn_formulaimage_0000001766331937.CEtissez.png",g=JSON.parse('{"title":"LayerNormGradBeta","description":"","frontmatter":{},"headers":[{"level":1,"title":"LayerNormGradBeta","slug":"layernormgradbeta"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/归一化操作/LayerNormGradBeta.md","filePath":"api/SIMD-API/高阶API/归一化操作/LayerNormGradBeta.md"}'),r={name:"api/SIMD-API/高阶API/归一化操作/LayerNormGradBeta.md"};function i(o,a,d,c,m,h){return t(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="layernormgradbeta" tabindex="-1">LayerNormGradBeta <a class="header-anchor" href="#layernormgradbeta" aria-label="Permalink to &quot;LayerNormGradBeta&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>LayerNormGradBeta接口用于获取反向beta/gamma的数值，和LayerNormGrad共同输出pdx, gamma和beta：</p><p>算法公式为:</p><p><img src="'+p+'" alt=""></p><p><img src="'+l+`" alt=""></p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><p>由于该接口的内部实现中涉及复杂的计算，需要额外的临时空间来存储计算过程中的中间变量。临时空间大小BufferSize的获取方法：通过<a href="./LayerNormGradBeta-Tiling.html">LayerNormGradBeta Tiling</a>中提供的GetLayerNormGradBetaMaxMinTmpSize接口获取所需最大和最小临时空间大小，最小空间可以保证功能正确，最大空间用于提升性能。</p><p>临时空间支持<strong>接口框架申请</strong>和开发者<strong>通过sharedTmpBuffer入参传入</strong>两种方式，因此LayerNormGradBeta接口的函数原型有两种：</p><ul><li><p>通过sharedTmpBuffer入参传入临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isReuseSource = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void LayerNormGradBeta(const LocalTensor&lt;T&gt;&amp; outputPdGamma, const LocalTensor&lt;T&gt;&amp; outputPdBeta, const LocalTensor&lt;T&gt;&amp; resForGamma, const LocalTensor&lt;T&gt;&amp; inputDy, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, const LayerNormGradBetaTiling&amp; tiling)</span></span></code></pre></div><p>该方式下开发者需自行申请并管理临时内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。</p></li><li><p>接口框架申请临时空间</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isReuseSource = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void LayerNormGradBeta(const LocalTensor&lt;T&gt;&amp; outputPdGamma, const LocalTensor&lt;T&gt;&amp; outputPdBeta, const LocalTensor&lt;T&gt;&amp; resForGamma, const LocalTensor&lt;T&gt;&amp; inputDy, LayerNormGradBetaTiling&amp; tiling)</span></span></code></pre></div><p>该方式下开发者无需申请，但是需要预留临时空间的大小。</p></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。支持的数据类型为：half、float。</td></tr><tr><td>isReuseSource</td><td>是否允许修改源操作数，默认值为false。如果开发者允许源操作数被改写，可以使能该参数，使能后能够节省部分内存空间。 设置为true，则本接口内部计算时复用inputDy的内存空间，节省内存空间；设置为false，则本接口内部计算时不复用inputDy的内存空间。 对于float数据类型输入支持开启该参数，half数据类型输入不支持开启该参数。 isReuseSource的使用样例请参考更多样例。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>outputPdGamma</td><td>输出</td><td>目的操作数，shape为[H]，LocalTensor数据结构的定义请参考LocalTensor。尾轴长度需要32B对齐 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>outputPdBeta</td><td>输出</td><td>目的操作数，shape为[H]，LocalTensor数据结构的定义请参考LocalTensor。尾轴长度需要32B对齐 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>resForGamma</td><td>输入</td><td>源操作数，shape为[B, S, H]，LocalTensor数据结构的定义请参考LocalTensor。resForGamma的数据类型需要与目的操作数保持一致，尾轴长度需要32B对齐。需提前调用LayerNormGrad接口获取resForGamma参数值。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>inputDy</td><td>输入</td><td>源操作数，shape为[B, S, H]，LocalTensor数据结构的定义请参考LocalTensor。inputDy的数据类型需要与目的操作数保持一致，尾轴长度需要32B对齐。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>共享缓冲区，用于存放API内部计算产生的临时数据。该方式开发者可以自行管理sharedTmpBuffer内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。共享缓冲区大小的获取方式请参考LayerNormGradBeta Tiling。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>tiling</td><td>输入</td><td>LayerNormGradBeta计算所需Tiling信息，Tiling信息的获取请参考LayerNormGradBeta Tiling。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="./../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li><li>源操作数和目的操作数的Tensor空间可以复用。</li><li>仅支持输入shape为ND格式。</li><li>输入数据不满足对齐要求时，开发者需要进行补齐，补齐的数据应设置为0，防止出现异常值从而影响网络计算。</li><li>不支持对尾轴H轴的切分。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// outputPdGamma: 输出对 gamma 参数的梯度，shape 为 [H]</span></span>
<span class="line"><span>// outputPdBeta: 输出对 beta 参数的梯度，shape 为 [H]</span></span>
<span class="line"><span>// resForGamma: 前一步 LayerNormGrad 输出的中间结果，即 normalizedX * inputDy，shape 为 [B, S, H]</span></span>
<span class="line"><span>// inputDy: 上游传入的梯度，shape 为 [B, S, H]</span></span>
<span class="line"><span>// tiling: Tiling 调度信息，包含并行划分、块大小等参数</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 使用 LayerNormGradBeta 接口计算 gamma 和 beta 的梯度</span></span>
<span class="line"><span>AscendC::LayerNormGradBeta&lt;T, isReuseSource&gt;(</span></span>
<span class="line"><span>    outputPdGamma,   // 输出：gamma 的梯度，shape [H]</span></span>
<span class="line"><span>    outputPdBeta,    // 输出：beta 的梯度，shape [H]</span></span>
<span class="line"><span>    resForGamma,     // 输入：中间结果 normalizedX * inputDy，来自 LayerNormGrad</span></span>
<span class="line"><span>    inputDy,         // 输入：上游梯度 dy，shape [B, S, H]</span></span>
<span class="line"><span>    tiling           // 输入：Tiling信息</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>示例结果如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(inputDy, shape:[1, 8, 8]): </span></span>
<span class="line"><span>[  0.  1.  2.  3.  4.  5.  6.  7.</span></span>
<span class="line"><span>   8.  9. 10. 11. 12. 13. 14. 15.</span></span>
<span class="line"><span>  16. 17. 18. 19. 20. 21. 22. 23.</span></span>
<span class="line"><span>  24. 25. 26. 27. 28. 29. 30. 31.</span></span>
<span class="line"><span>  32. 33. 34. 35. 36. 37. 38. 39.</span></span>
<span class="line"><span>  40. 41. 42. 43. 44. 45. 46. 47.</span></span>
<span class="line"><span>  48. 49. 50. 51. 52. 53. 54. 55.</span></span>
<span class="line"><span>  56. 57. 58. 59. 60. 61. 62. 63. ]</span></span>
<span class="line"><span>输入数据(resForGamma, shape:[1, 8, 8]): </span></span>
<span class="line"><span>[  0.  1.  2.  3.  4.  5.  6.  7.</span></span>
<span class="line"><span>   8.  9. 10. 11. 12. 13. 14. 15.</span></span>
<span class="line"><span>  16. 17. 18. 19. 20. 21. 22. 23.</span></span>
<span class="line"><span>  24. 25. 26. 27. 28. 29. 30. 31.</span></span>
<span class="line"><span>  32. 33. 34. 35. 36. 37. 38. 39.</span></span>
<span class="line"><span>  40. 41. 42. 43. 44. 45. 46. 47.</span></span>
<span class="line"><span>  48. 49. 50. 51. 52. 53. 54. 55.</span></span>
<span class="line"><span>  56. 57. 58. 59. 60. 61. 62. 63. ]</span></span>
<span class="line"><span>输出数据(outputPdGamma): </span></span>
<span class="line"><span>[ 8960.  9416.  9888. 10376. 10880. 11400. 11936. 12488.]</span></span>
<span class="line"><span>输出数据(outputPdBeta): </span></span>
<span class="line"><span>[ 224. 232. 240. 248. 256. 264. 272. 280. ]</span></span></code></pre></div>`,25)])])}const T=s(r,[["render",i]]);export{g as __pageData,T as default};
